using UnityEngine;
using Game.Character;
using Game.Input;

namespace Game.Stage
{
    /// <summary>
    /// ステージ生成時にプレイヤーと各Managerを接続する。
    ///
    /// 動的に生成されたPlayer Prefabへ必要な参照を渡す。
    /// ステージ状態に応じた入力モード変更と
    /// ポーズ・再開操作も担当する。
    /// </summary>
    [DisallowMultipleComponent]
    public class MazePlayerStageBinder : MonoBehaviour
    {
        #region Inspector Fields

        [Header("参照設定")]

        /// <summary>ステージ管理クラス。</summary>
        [SerializeField]
        [Tooltip("接続対象のMazeStageManager")]
        private MazeStageManager stageManager;

        /// <summary>ステージオブジェクト生成クラス。</summary>
        [SerializeField]
        [Tooltip("プレイヤーを生成するMazeStageSpawner")]
        private MazeStageSpawner stageSpawner;

        /// <summary>ゲーム入力管理クラス。</summary>
        [SerializeField]
        [Tooltip("プレイヤー操作に使用するGameInputManager")]
        private GameInputManager inputManager;

        [Header("入力連携設定")]

        /// <summary>ステージ状態と入力モードを連携するか。</summary>
        [SerializeField]
        [Tooltip("ステージ状態に応じて入力モードを変更する")]
        private bool synchronizeInputMode = true;

        /// <summary>ポーズ・再開入力を処理するか。</summary>
        [SerializeField]
        [Tooltip("ポーズボタンとキャンセルボタンを処理する")]
        private bool handlePauseInput = true;

        #endregion

        #region Runtime Fields

        /// <summary>現在接続されているプレイヤー。</summary>
        private MazePlayerController currentPlayer;

        /// <summary>イベント登録が完了しているか。</summary>
        private bool isSubscribed;

        #endregion

        #region Properties

        /// <summary>現在のプレイヤーを取得する。</summary>
        public MazePlayerController CurrentPlayer =>
            currentPlayer;

        /// <summary>プレイヤーとの接続が完了しているか。</summary>
        public bool HasPlayer =>
            currentPlayer != null &&
            currentPlayer.IsInitialized;

        #endregion

        #region Unity Methods

        /// <summary>コンポーネント有効化時の処理。</summary>
        private void OnEnable()
        {
            if (!ValidateReferences())
            {
                return;
            }

            // StageManagerのStartより前にイベントを登録する。
            stageManager.StageGenerated += OnStageGenerated;

            stageManager.StateChanged += OnStageStateChanged;

            isSubscribed = true;

            // 既に生成済みの場合にも対応する。
            if (stageManager.HasStage)
            {
                BindPlayer(stageManager.StageResult);
            }

            SynchronizeInputMode();
        }

        /// <summary>シーン開始時の処理。</summary>
        private void Start()
        {
            if (!isSubscribed)
            {
                return;
            }

            // Awakeの実行順序による初期化漏れを防止する。
            if (!inputManager.IsInitialized)
            {
                inputManager.Initialize();
            }

            if (stageManager.HasStage && !HasPlayer)
            {
                BindPlayer(stageManager.StageResult);
            }

            SynchronizeInputMode();
        }

        /// <summary>ポーズ・再開入力を毎フレーム確認する。</summary>
        private void Update()
        {
            if (!isSubscribed ||
                !handlePauseInput ||
                !inputManager.IsInitialized)
            {
                return;
            }

            if (stageManager.State == MazeStageState.Playing)
            {
                if (inputManager.GetButtonDown(
                    GameInputAction.Pause))
                {
                    stageManager.PauseStage();
                }
            }
            else if (
                stageManager.State == MazeStageState.Paused)
            {
                if (inputManager.GetButtonDown(
                    GameInputAction.Cancel))
                {
                    stageManager.ResumeStage();
                }
            }
        }

        /// <summary>コンポーネント無効化時の処理。</summary>
        private void OnDisable()
        {
            if (isSubscribed && stageManager != null)
            {
                stageManager.StageGenerated -=
                    OnStageGenerated;

                stageManager.StateChanged -=
                    OnStageStateChanged;
            }

            isSubscribed = false;

            ReleasePlayer();
        }

        #endregion

        #region Player Binding Methods

        /// <summary>
        /// ステージ生成完了時のイベント処理。
        /// </summary>
        /// <param name="result">生成されたステージ情報</param>
        private void OnStageGenerated(
            MazeStageGenerationResult result)
        {
            BindPlayer(result);
        }

        /// <summary>
        /// 生成されたプレイヤーを各Managerへ接続する。
        /// </summary>
        /// <param name="result">生成されたステージ情報</param>
        /// <returns>接続に成功した場合はtrue</returns>
        private bool BindPlayer(
            MazeStageGenerationResult result)
        {
            ReleasePlayer();

            if (result == null)
            {
                return false;
            }

            if (!inputManager.IsInitialized &&
                !inputManager.Initialize())
            {
                Debug.LogError(
                    "入力システムの初期化に失敗しました。",
                    this);

                return false;
            }

            GameObject playerObject =
                stageSpawner.PlayerInstance;

            if (playerObject == null)
            {
                Debug.LogError(
                    "プレイヤーが生成されていません。",
                    this);

                return false;
            }

            MazePlayerController player =
                playerObject.GetComponent<MazePlayerController>();

            if (player == null)
            {
                Debug.LogError(
                    "Player PrefabにMazePlayerControllerが" +
                    "設定されていません。",
                    playerObject);

                return false;
            }

            if (!player.Initialize(
                stageManager,
                inputManager,
                result.PlayerSpawnPosition))
            {
                Debug.LogError(
                    "プレイヤーの初期化に失敗しました。",
                    playerObject);

                return false;
            }

            currentPlayer = player;

            Debug.Log(
                $"プレイヤー接続完了：" +
                $"{result.PlayerSpawnPosition}",
                this);

            return true;
        }

        /// <summary>現在のプレイヤーとの接続を解除する。</summary>
        private void ReleasePlayer()
        {
            if (currentPlayer != null)
            {
                currentPlayer.Shutdown();
            }

            currentPlayer = null;
        }

        #endregion

        #region Stage State Methods

        /// <summary>ステージ状態変更時のイベント処理。</summary>
        /// <param name="previousState">変更前の状態</param>
        /// <param name="newState">変更後の状態</param>
        private void OnStageStateChanged(
            MazeStageState previousState,
            MazeStageState newState)
        {
            // ステージ再生成時には古いプレイヤーを解除する。
            if (newState == MazeStageState.Generating ||
                newState == MazeStageState.None)
            {
                ReleasePlayer();
            }

            SynchronizeInputMode();
        }

        /// <summary>
        /// 現在のステージ状態を入力モードへ反映する。
        /// </summary>
        private void SynchronizeInputMode()
        {
            if (!synchronizeInputMode ||
                inputManager == null ||
                !inputManager.IsInitialized)
            {
                return;
            }

            GameInputMode mode;

            switch (stageManager.State)
            {
                case MazeStageState.Playing:

                    mode = GameInputMode.Gameplay;
                    break;

                case MazeStageState.Paused:
                case MazeStageState.Cleared:
                case MazeStageState.Failed:
                case MazeStageState.Ready:

                    mode = GameInputMode.UI;
                    break;

                default:

                    mode = GameInputMode.Disabled;
                    break;
            }

            inputManager.SetInputMode(mode);
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// 必要な参照が設定されているか確認する。
        /// </summary>
        /// <returns>参照が正常な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (stageManager == null ||
                stageSpawner == null ||
                inputManager == null)
            {
                Debug.LogError(
                    "MazePlayerStageBinderに必要な参照が" +
                    "設定されていません。",
                    this);

                return false;
            }

            return true;
        }

        #endregion
    }
}
